import type { EngineInterface, PluginOptions, Register } from 'claude-code'
import type { Gemini, GeminiChange, GeminiEnroll, GeminiPrepared, GeminiRequest, GeminiSettings, GeminiTier } from '../types/index.d.ts'
import { buildHttp, MODEL_ID, withThinking } from './api.ts'
import { parseKeys, readWithKeys, type KeyState } from './keys.ts'
import { modelsRequest, modelsText, parseModels, unknownModel, type ModelInfo } from './models.ts'
import { listTree, PANE_ID, paneRows, pickerTree, type Pick } from './picker.tsx'
import { consumersOf, FREE_WARNING, isThinking, isTier, KEYS, ownModelsText, parseCommand, resolveConsumer, statusText, type ConsumerLine } from './settings.ts'

/**
 * The store and environment the methods of `$.gemini` run on. The validator
 * refuses `next(e)` at `engine.create` passed as an argument, so the hook wraps
 * the calls it needs.
 */
export type Host = {
  get(key: string): Promise<unknown>
  set(key: string, value: unknown): Promise<void>
  del(key: string): Promise<void>
  envKey(): Promise<string | undefined>
}

/** `apiKeys` from the option, tried in order; empty when the option is unset. */
export type Config = { apiKeys: string[]; tier: GeminiTier }

const NO_KEY = 'no Gemini key: set GEMINI_API_KEY or the gemini-core apiKey option'

export function configFrom(options: PluginOptions): Config {
  return { apiKeys: parseKeys(typeof options.apiKey === 'string' ? options.apiKey : undefined), tier: isTier(options.tier) ? options.tier : 'free' }
}

function errorText(err: unknown): string {
  return err instanceof Error ? err.message : String(err)
}

/** The option's keys, or else the keys of GEMINI_API_KEY; both take a comma-separated list. */
async function apiKeys(host: Host, config: Config): Promise<string[]> {
  return config.apiKeys.length > 0 ? config.apiKeys : parseKeys(await host.envKey())
}

async function tierOf(host: Host, config: Config): Promise<GeminiTier> {
  const stored = await host.get(KEYS.tier)
  return isTier(stored) ? stored : config.tier
}

async function enrolled(host: Host): Promise<Record<string, string>> {
  return consumersOf(await host.get(KEYS.consumers))
}

async function settingsFor(host: Host, config: Config, consumer: string): Promise<GeminiSettings> {
  const defaultModel = (await enrolled(host))[consumer]
  if (defaultModel === undefined) throw new Error(`${consumer} has not enrolled with gemini-core`)
  const model = await host.get(KEYS.model(consumer))
  const thinking = await host.get(KEYS.thinking(consumer))
  const own = (await host.get(KEYS.own(consumer))) === true
  const keys = (await apiKeys(host, config)).length
  return {
    hasKey: keys > 0,
    keys,
    tier: await tierOf(host, config),
    model: typeof model === 'string' && MODEL_ID.test(model) ? model : defaultModel,
    ...(isThinking(thinking) ? { thinking } : {}),
    ...(own ? { ownModels: true as const } : {}),
  }
}

/** Keeps whether a mod names the model of each request itself, as its latest enrollment says. */
async function markOwnModels(host: Host, consumer: string, own: boolean): Promise<void> {
  if (((await host.get(KEYS.own(consumer))) === true) === own) return
  if (own) await host.set(KEYS.own(consumer), true)
  else await host.del(KEYS.own(consumer))
}

async function enroll(host: Host, input: GeminiEnroll): Promise<void> {
  if (!/^[a-z0-9][a-z0-9-]*$/.test(input.consumer)) throw new Error(`enroll takes a plugin name, not ${JSON.stringify(input.consumer)}`)
  if (!MODEL_ID.test(input.defaultModel)) throw new Error(`enroll takes a Gemini model id, not ${JSON.stringify(input.defaultModel)}`)
  const mods = await enrolled(host)
  if (mods[input.consumer] !== input.defaultModel) await host.set(KEYS.consumers, { ...mods, [input.consumer]: input.defaultModel })
  await markOwnModels(host, input.consumer, input.ownModels === true)
}

/** The request for a mod, with the key the last request succeeded or moved on with, and the model the input names, if any. */
async function prepareRequest(host: Host, config: Config, state: KeyState, input: GeminiRequest): Promise<GeminiPrepared> {
  if (input.model !== undefined && !MODEL_ID.test(input.model)) return { error: `${input.model} is not a Gemini model id` }
  const keys = await apiKeys(host, config)
  const key = keys[state.preferred] ?? keys[0]
  if (key === undefined) return { error: NO_KEY }
  try {
    const s = await settingsFor(host, config, input.consumer)
    const model = input.model ?? s.model
    return { http: buildHttp(model, key, withThinking(input.body, s.thinking)), model, tier: s.tier }
  } catch (err) {
    return { error: errorText(err) }
  }
}

async function reset(host: Host): Promise<string> {
  await host.del(KEYS.tier)
  for (const consumer of Object.keys(await enrolled(host))) {
    await host.del(KEYS.model(consumer))
    await host.del(KEYS.thinking(consumer))
  }
  return 'settings reset: the plugin option tier, and each mod its default model and the model default thinking'
}

/** A model or thinking change for one mod, named in full or without `gemini-`. */
async function configureMod(host: Host, change: Extract<GeminiChange, { consumer: string }>): Promise<string> {
  const names = Object.keys(await enrolled(host))
  const consumer = resolveConsumer(change.consumer, names)
  if (consumer === undefined) throw new Error(`no Gemini mod named ${change.consumer}; enrolled: ${names.join(', ') || 'none'}`)
  if ('model' in change) {
    if ((await host.get(KEYS.own(consumer))) === true) throw new Error(ownModelsText(consumer))
    if (!MODEL_ID.test(change.model)) throw new Error(`${change.model} is not a Gemini model id`)
    await host.set(KEYS.model(consumer), change.model)
    return `${consumer}: model ${change.model}`
  }
  if (change.thinking === null) await host.del(KEYS.thinking(consumer))
  else await host.set(KEYS.thinking(consumer), change.thinking)
  return `${consumer}: thinking ${change.thinking ?? 'model default'}`
}

async function configure(host: Host, change: GeminiChange): Promise<string> {
  if ('reset' in change) return reset(host)
  if ('tier' in change) {
    await host.set(KEYS.tier, change.tier)
    return change.tier === 'free' ? FREE_WARNING : 'paid tier'
  }
  return configureMod(host, change)
}

/** `$.gemini`, on the nouns beneath it. */
export function createGemini(host: Host, config: Config): Gemini {
  const state: KeyState = { preferred: 0 }
  return {
    enroll: input => enroll(host, input),
    settings: ({ consumer }) => settingsFor(host, config, consumer),
    request: input => prepareRequest(host, config, state, input),
    read: async input => readWithKeys(input, await apiKeys(host, config), state),
    configure: change => configure(host, change),
  }
}

async function statusOf($: EngineInterface, config: Config): Promise<string> {
  const mods = Object.keys(consumersOf(await $.store.get(KEYS.consumers))).sort()
  const lines: ConsumerLine[] = []
  for (const consumer of mods) {
    const s = await $.gemini.settings({ consumer })
    lines.push({ consumer, model: s.model, ...(s.thinking === undefined ? {} : { thinking: s.thinking }), ...(s.ownModels === true ? { ownModels: true as const } : {}) })
  }
  const tier = await $.store.get(KEYS.tier)
  const keys = config.apiKeys.length > 0 ? config.apiKeys : parseKeys(await $.env.get('GEMINI_API_KEY'))
  return statusText(isTier(tier) ? tier : config.tier, keys.length, lines)
}

/** What the command keeps for the session: the model list, fetched once, and the pick the pane is open for. */
type Session = { models?: ModelInfo[]; pick?: Pick }

/** The text models the keys list, from memory unless `refresh`; each key is asked in turn until one answers. */
async function listModels($: EngineInterface, config: Config, session: Session, refresh: boolean): Promise<ModelInfo[]> {
  if (session.models !== undefined && !refresh) return session.models
  const keys = config.apiKeys.length > 0 ? config.apiKeys : parseKeys(await $.env.get('GEMINI_API_KEY'))
  if (keys.length === 0) throw new Error(NO_KEY)
  const failures: string[] = []
  for (const [i, key] of keys.entries()) {
    const request = modelsRequest(key)
    const r = await $.http.fetch(request.url, request.init)
    try {
      session.models = parseModels(r.status, r.ok, r.text)
      return session.models
    } catch (err) {
      failures.push(`key ${i + 1}: ${errorText(err)}`)
    }
  }
  throw new Error(failures.join('; '))
}

/** Opens the pane that lists the models for one mod. */
async function openPicker($: EngineInterface, config: Config, session: Session, name: string): Promise<string> {
  const names = Object.keys(consumersOf(await $.store.get(KEYS.consumers)))
  const consumer = resolveConsumer(name, names)
  if (consumer === undefined) return `no Gemini mod named ${name}; enrolled: ${names.join(', ') || 'none'}`
  if ((await $.store.get(KEYS.own(consumer))) === true) return ownModelsText(consumer)
  const models = await listModels($, config, session, false)
  if (models.length === 0) return modelsText(models)
  session.pick = { consumer, models, current: (await $.gemini.settings({ consumer })).model }
  await $.ui.open({ id: PANE_ID, title: `Gemini model for ${consumer}`, focus: true, closeOnEscape: true, rows: paneRows(models) })
  return `pick the model of ${consumer} in the pane; Esc closes it`
}

/** Sets the model picked in the pane and closes it. */
async function pickModel($: EngineInterface, session: Session, model: string): Promise<void> {
  const pick = session.pick
  if (pick === undefined) return
  session.pick = undefined
  await $.ui.close({ id: PANE_ID })
  $.ui.toast(await $.gemini.configure({ consumer: pick.consumer, model }))
}

/** Whether the mod named in a command names the model of each request itself. */
async function ownsModels($: EngineInterface, name: string): Promise<boolean> {
  const consumer = resolveConsumer(name, Object.keys(consumersOf(await $.store.get(KEYS.consumers))))
  return consumer !== undefined && (await $.store.get(KEYS.own(consumer))) === true
}

/**
 * A model id set by argument is checked against the list the keys give; a mod that names its own models
 * is refused by `configure` before the list is asked for.
 */
async function applyChange($: EngineInterface, config: Config, session: Session, change: GeminiChange): Promise<string> {
  if ('model' in change && !(await ownsModels($, change.consumer))) {
    const refused = unknownModel(change.model, await listModels($, config, session, false))
    if (refused !== undefined) return refused
  }
  return $.gemini.configure(change)
}

async function runCommand($: EngineInterface, config: Config, session: Session, args: string): Promise<string> {
  const command = parseCommand(args)
  try {
    switch (command.kind) {
      case 'error': return command.text
      case 'status': return await statusOf($, config)
      case 'models': return modelsText(await listModels($, config, session, command.refresh))
      case 'pick': return await openPicker($, config, session, command.consumer)
      case 'change': return await applyChange($, config, session, command.change)
    }
  } catch (err) {
    return errorText(err)
  }
}

export const register: Register = (on, options) => {
  const config = configFrom(options)
  const session: Session = {}

  on('engine.create', async (_, e, next) => {
    const below = await next(e)
    const host: Host = {
      get: key => below.store.get(key),
      set: (key, value) => below.store.set(key, value),
      del: key => below.store.delete(key),
      envKey: () => below.env.get('GEMINI_API_KEY'),
    }
    return { ...below, gemini: createGemini(host, config) }
  })

  on('session.start', async ($, e, next) => {
    const r = await next(e)
    await $.command.register({
      name: 'gemini-core',
      description: 'Gemini settings of every Gemini mod: status, free, paid, models, model <mod> [id], thinking <mod> <level|default>, reset (gemini-core)',
      argumentHint: '[free | paid | models [refresh] | model <mod> [id] | thinking <mod> <level|default> | reset]',
    })
    return r
  })

  on('command.run', { command: 'gemini-core' }, async ($, e) => ({ text: await runCommand($, config, session, String(e.args ?? '')) }))

  on('ui.render', { component: 'Pane' }, async ($, e, next) => {
    const pick = session.pick
    if (e.requestId !== PANE_ID || pick === undefined) return next(e)
    if (e.surface === 'mobile') return listTree($.ui.resolve(e), pick)
    return pickerTree($.ui.resolve(e), pick, model => void pickModel($, session, model).catch((err: unknown) => $.ui.toast(errorText(err))))
  })

  // Esc or the person closing the pane drops the pick.
  on('ui.close', async (_, e, next) => {
    if (e.id === PANE_ID) session.pick = undefined
    return next(e)
  })
}

